// Authorized initial and replacement requests. Eligibility references are revalidated by the existing save command.
let mentorRequestQueue=null,mentorRequestQueueGeneration=0,mentorRequestDetailGeneration=0,mentorRequestDetail=null,mentorRequestLock=null;
function mentorRequestItem(v){const id=x=>typeof x==='string'&&/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(x);if(!v||!id(v.proposalId)||!id(v.firstReviewId)||!v.firstReviewId.startsWith(v.proposalId+':first-review:')||!Number.isSafeInteger(v.submissionVersion)||v.submissionVersion<1||(!Number.isSafeInteger(v.expectedAssignmentVersion)||v.expectedAssignmentVersion<0)||typeof v.title!=='string'||v.title.length>120)throw Error('Mentor request is unavailable.');return Object.fromEntries(['proposalId','firstReviewId','submissionVersion','title','expectedAssignmentVersion'].map(k=>[k,v[k]]))}
function resetMentorRequestClient(){mentorRequestQueue=null;mentorRequestDetail=null;mentorRequestQueueGeneration++;mentorRequestDetailGeneration++;if(mentorRequestLock){mentorRequestLock=null;lockShared(false)}if(document.querySelector('#mentor-request-detail')&&$('#modal').open)closeModal()}
function currentMentorRequestQueue(){return mentorRequestQueue&&intakeMentorClientCurrent(mentorRequestQueue.context)?mentorRequestQueue:null}
async function refreshMentorRequestQueue(offset=0){
 if(!sharedReady||db.intakeTeamAccess?.enabled!==true)return resetMentorRequestClient();
 const c=intakeMentorClientContext(),generation=++mentorRequestQueueGeneration;mentorRequestQueue=null;
 try{const r=await sharedFetch('/api/workspace',{command:'readIntakeTeamMentorRequestQueue',actor:c.actor,revision:c.revision,args:[{offset,limit:20}],context:{page:'Activity Intake'}});if(generation!==mentorRequestQueueGeneration||!intakeMentorClientCurrent(c))return;intakeMentorClientProtocol(r,c,'MENTOR_REQUEST_QUEUE');const q=r.selection;
 if(!q||!Array.isArray(q.items)||!Number.isSafeInteger(q.total)||q.total<0||q.offset!==offset||q.limit!==20||q.items.length!==Math.min(20,Math.max(0,q.total-offset)))throw Error('Mentor request page changed.');const items=q.items.map(mentorRequestItem);if(new Set(items.map(v=>v.proposalId)).size!==items.length)throw Error('Duplicate request references.');mentorRequestQueue={context:c,items,total:q.total,offset};if(['Overview','Activity Intake'].includes(page))render();
 }catch(e){if(generation===mentorRequestQueueGeneration&&intakeMentorClientCurrent(c)){mentorRequestQueue=null;if(e.status!==503)toast('Mentor request access changed. Refresh the workspace.');if(['Overview','Activity Intake'].includes(page))render()}}
}
function mentorRequestPanel(){const q=currentMentorRequestQueue();return q?.total?`<section class="panel"><h2>Request a team mentor</h2><p>Reviewed team proposals awaiting your authorized mentor assignment.</p>${q.items.map((v,i)=>`<button type="button" data-mentor-request-open="${i}">${v.expectedAssignmentVersion?'Select replacement':'Select mentor'} · ${esc(v.title)}</button>`).join('')}<p>${q.items.length?q.offset+1:0}–${Math.min(q.offset+q.items.length,q.total)} of ${q.total}</p>${q.offset?'<button type="button" data-mentor-request-queue-page="'+Math.max(0,q.offset-20)+'">Previous</button>':''}${q.offset+20<q.total&&q.offset+20<=10000?'<button type="button" data-mentor-request-queue-page="'+(q.offset+20)+'">Next</button>':''}<button type="button" data-mentor-request-queue-page="0">Refresh requests</button></section>`:''}
function mentorRequestCurrent(d){return mentorRequestDetail===d&&intakeMentorClientCurrent(d.context)&&currentMentorRequestQueue()===d.queue}
function cleanMentorSelection(v,item,offset){
 const actual=mentorRequestItem(v?.item),id=x=>typeof x==='string'&&/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(x);if(['proposalId','firstReviewId','submissionVersion','expectedAssignmentVersion'].some(k=>actual[k]!==item[k])||!v.proposal||!['title','type','programme','purpose','outputs','start','due'].every(k=>typeof v.proposal[k]==='string'&&v.proposal[k].length<=3000)||typeof v.consultationRequired!=='boolean'||!Array.isArray(v.candidates)||!Number.isSafeInteger(v.total)||v.total<0||v.offset!==offset||v.limit!==20||v.candidates.length!==Math.min(20,Math.max(0,v.total-offset))||new Set(v.candidates.map(x=>x.mentor)).size!==v.candidates.length||!v.candidates.every(x=>id(x.mentor)&&typeof x.displayName==='string'&&x.displayName.length<=200&&typeof x.selectionToken==='string'&&/^[a-f0-9]{64}$/.test(x.selectionToken)))throw Error('Mentor eligibility changed.');
 const result={item:actual,proposal:Object.fromEntries(['title','type','programme','purpose','outputs','start','due'].map(k=>[k,v.proposal[k]])),consultationRequired:v.consultationRequired,candidates:v.candidates.map(x=>({mentor:x.mentor,displayName:x.displayName,selectionToken:x.selectionToken})),total:v.total,offset};if(v.mentorSuggestion){if(typeof v.mentorSuggestion.name!=='string'||v.mentorSuggestion.name.length>200||typeof v.mentorSuggestion.reason!=='string'||v.mentorSuggestion.reason.length>1000)throw Error('Mentor preference is unavailable.');result.mentorSuggestion={name:v.mentorSuggestion.name,reason:v.mentorSuggestion.reason}}return result;
}
function mentorRequestProposalHTML(d){const p=d.proposal;return `${d.item.expectedAssignmentVersion?'<p>Replacement after withdrawn assignment v'+d.item.expectedAssignmentVersion+'. Previous assignment records are retained; fresh acceptance is required.</p>':''}<h2>${esc(d.item.title)}</h2><p>${esc(d.item.proposalId)} · submitted v${d.item.submissionVersion} · ${esc(p.type)} · ${esc(p.programme)}</p><p>${esc(p.start)} to ${esc(p.due)}</p><h3>Purpose</h3><p>${esc(p.purpose)}</p><h3>Expected outputs</h3><p>${esc(p.outputs)}</p>${d.mentorSuggestion?'<h3>Student mentor preference</h3><p>'+esc(d.mentorSuggestion.name)+' · '+esc(d.mentorSuggestion.reason)+'</p><p>A preference does not appoint the mentor.</p>':''}${d.consultationRequired?'<p>Interdepartmental consultation remains a separate required step.</p>':''}`}
async function openMentorRequest(index,offset=0){
 const q=currentMentorRequestQueue();if(!q||sharedBusy||!Number.isSafeInteger(index)||!q.items[index]||!Number.isSafeInteger(offset)||offset<0||offset>10000)return;
 const c=q.context,item=q.items[index],generation=++mentorRequestDetailGeneration,token={};mentorRequestDetail=null;mentorRequestLock=token;modal('<section id="mentor-request-detail"><h2>Checking mentor eligibility…</h2></section>');const marker=document.querySelector('#mentor-request-detail');lockShared(true);
 try{const r=await sharedFetch('/api/workspace',{command:'readIntakeTeamMentorCandidates',actor:c.actor,revision:c.revision,args:[{proposalId:item.proposalId,offset,limit:20}],context:{page:'Activity Intake'}});if(generation!==mentorRequestDetailGeneration||!intakeMentorClientCurrent(c)||currentMentorRequestQueue()!==q||!$('#modal').open||document.querySelector('#mentor-request-detail')!==marker)return;intakeMentorClientProtocol(r,c,'MENTOR_CANDIDATES');const clean=cleanMentorSelection(r.selection,item,offset),d={...clean,context:c,queue:q,index};mentorRequestDetail=d;
 modal(`<section id="mentor-request-detail">${mentorRequestProposalHTML(d)}<h3>Select an eligible mentor</h3>${d.candidates.length?d.candidates.map((v,i)=>`<button type="button" data-mentor-request-candidate="${i}">${esc(v.displayName)} · ${esc(v.mentor)}</button>`).join(''):'<p>No currently eligible mentors are available on this page.</p>'}<p>${d.candidates.length?offset+1:0}–${Math.min(offset+d.candidates.length,d.total)} of ${d.total}</p>${offset?'<button type="button" data-mentor-request-candidate-page="'+Math.max(0,offset-20)+'">Previous mentors</button>':''}${offset+20<d.total&&offset+20<=10000?'<button type="button" data-mentor-request-candidate-page="'+(offset+20)+'">Next mentors</button>':''}<p>Selection prepares a request. The mentor must accept before supervision is confirmed.</p></section>`);d.marker=document.querySelector('#mentor-request-detail');
 }catch(e){if(generation===mentorRequestDetailGeneration&&intakeMentorClientCurrent(c)){closeModal();resetMentorRequestClient();toast('Mentor selection changed. Refresh and reopen this proposal.')}}finally{if(mentorRequestLock===token){mentorRequestLock=null;lockShared(false)}}
}
function chooseMentorRequestCandidate(index){const d=mentorRequestDetail;if(!d||sharedBusy||!mentorRequestCurrent(d)||!$('#modal').open||document.querySelector('#mentor-request-detail')!==d.marker||!Number.isSafeInteger(index)||!d.candidates[index])return;d.chosen=d.candidates[index];modal(`<section id="mentor-request-detail">${mentorRequestProposalHTML(d)}<h3>Request acceptance from ${esc(d.chosen.displayName)}</h3><p>Mentor: ${esc(d.chosen.mentor)}</p><form id="mentor-request-form"><label>Expertise / activity fit<textarea name="fit" required maxlength="2000"></textarea></label><label>Availability and capacity assessment<textarea name="capacity" required maxlength="2000"></textarea></label><label>Assignment reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirmed" value="yes" required> I have reviewed the proposal and selected mentor and want to request their acceptance.</label><p>The mentor must accept. This request does not complete consultation, grant final approval or authorize execution.</p><button type="submit">Confirm mentor request</button></form></section>`);d.marker=document.querySelector('#mentor-request-detail')}
async function saveSelectedMentorRequest(fields){
 const d=mentorRequestDetail;if(!d||sharedBusy||!mentorRequestCurrent(d)||!d.chosen||!d.candidates.includes(d.chosen)||!$('#modal').open||document.querySelector('#mentor-request-detail')!==d.marker)return toast('Refresh and reopen the current mentor selection.');
 if(!fields||Object.keys(fields).some(k=>!['fit','capacity','reason','confirmed'].includes(k))||fields.confirmed!=='yes'||!['fit','capacity','reason'].every(k=>typeof fields[k]==='string'&&fields[k].trim().length>0&&fields[k].trim().length<=2000))return toast('Complete the expertise, capacity and reason assessments, then confirm this mentor request.');
 const c=d.context,token={},generation=++mentorRequestDetailGeneration;mentorRequestLock=token;lockShared(true);
 try{const r=await sharedFetch('/api/workspace',{command:'requestIntakeTeamMentor',actor:c.actor,revision:c.revision,args:[{proposalId:d.item.proposalId,firstReviewId:d.item.firstReviewId,submissionVersion:d.item.submissionVersion,expectedAssignmentVersion:d.item.expectedAssignmentVersion,mentor:d.chosen.mentor,selectionToken:d.chosen.selectionToken,fit:fields.fit.trim(),capacity:fields.capacity.trim(),reason:fields.reason.trim()}],context:{page:'Activity Intake'}});if(generation!==mentorRequestDetailGeneration||!mentorRequestCurrent(d))return;
 const a=r?.assignment;if(r?.kind!=='INTAKE_TEAM_COMMAND'||r.action!=='MENTOR_REQUEST'||r.actor!==c.actor||r.revision!==c.revision+1||!a||['proposalId','firstReviewId','submissionVersion'].some(k=>a[k]!==d.item[k])||typeof a.assignmentId!=='string'||!/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(a.assignmentId)||a.assignmentVersion!==d.item.expectedAssignmentVersion+1||a.state!=='REQUESTED'||a.workspaceRevision!==r.revision||a.executionAuthorized!==false)throw Error('Mentor request response changed.');
 const fresh=await sharedFetch('/api/workspace');if(generation!==mentorRequestDetailGeneration||!mentorRequestCurrent(d))return;if(fresh?.actor!==c.actor||!Number.isSafeInteger(fresh.revision)||fresh.revision<r.revision||!Array.isArray(fresh.data?.projects))throw Error('A fresh workspace is required.');closeModal();resetMentorRequestClient();applyShared(fresh);toast('Mentor request saved. The assigned mentor must accept; approval and permission to start remain separate.');
 }catch(e){if(generation===mentorRequestDetailGeneration&&mentorRequestCurrent(d)){closeModal();resetMentorRequestClient();toast('Unable to confirm the mentor request. Refresh the workspace and check its status before trying again.')}}finally{if(mentorRequestLock===token){mentorRequestLock=null;lockShared(false)}}
}
const mentorRequestPriorRefresh=refreshIntakeTeamAccess;
refreshIntakeTeamAccess=async function(){resetMentorRequestClient();await mentorRequestPriorRefresh();if(sharedReady&&db.intakeTeamAccess?.enabled===true)await refreshMentorRequestQueue()};
const mentorRequestPriorReset=resetIntakeTeamClient;
resetIntakeTeamClient=function(){resetMentorRequestClient();return mentorRequestPriorReset()};
const mentorRequestPriorOverview=overview;
overview=function(){const q=currentMentorRequestQueue();return mentorRequestPriorOverview()+(q?.total?`<section class="panel"><h2>Mentor requests to prepare</h2><p>${q.total} reviewed team proposal${q.total===1?'':'s'} awaiting mentor assignment within your authority.</p>${btn('Open module overview',"go('Activity Intake')")}</section>`:'')};
const mentorRequestPriorIntakes=activityIntakesPage;
activityIntakesPage=function(){return mentorRequestPanel()+mentorRequestPriorIntakes()};
document.addEventListener('click',event=>{const b=event.target.closest?.('[data-mentor-request-open]');if(b){openMentorRequest(Number(b.dataset.mentorRequestOpen));return}const c=event.target.closest?.('[data-mentor-request-candidate]');if(c){chooseMentorRequestCandidate(Number(c.dataset.mentorRequestCandidate));return}const p=event.target.closest?.('[data-mentor-request-candidate-page]');if(p&&mentorRequestDetail){openMentorRequest(mentorRequestDetail.index,Number(p.dataset.mentorRequestCandidatePage));return}const q=event.target.closest?.('[data-mentor-request-queue-page]');if(q&&!sharedBusy){const offset=Number(q.dataset.mentorRequestQueuePage);if(Number.isSafeInteger(offset)&&offset>=0&&offset<=10000)refreshMentorRequestQueue(offset)}});
document.addEventListener('submit',event=>{if(event.target?.id!=='mentor-request-form')return;event.preventDefault();saveSelectedMentorRequest(Object.fromEntries(new FormData(event.target)))});
